// Host build: an overlay unit's list of its variables, reset when the overlay is loaded (modern/host/overlay.c).
//
// On the DS, loading an overlay reads a fresh copy of its data from the ROM, clears its bss and runs its static
// initialisers. The host has every overlay linked in, so each overlay unit (src/ovNNN/) lists its variables at its
// end, generated by tools/host_overlay_vars.py (HOST_OVERLAY_VARS); modern/gen/overlay_table.c collects the lists
// and the units' explicit initialisers (StaticInit_<unit>) per overlay. See docs/host.md.
#ifndef HOST_OVERLAY_VARS_H
#define HOST_OVERLAY_VARS_H

typedef struct HostOverlayVar {
    void *addr;
    __SIZE_TYPE__ size;
    const char *name;
} HostOverlayVar;

#ifdef __cplusplus
#define HOST_OVERLAY_VARS_LINKAGE extern "C"
#else
#define HOST_OVERLAY_VARS_LINKAGE extern
#endif

// HOST_OVERLAY_VARS(unit) { HOST_OVERLAY_VAR(a), HOST_OVERLAY_VAR(b), HOST_OVERLAY_VARS_END };
#define HOST_OVERLAY_VARS(unit)                                                                                      \
    HOST_OVERLAY_VARS_LINKAGE const HostOverlayVar gHostOvVars_##unit[];                                             \
    HOST_OVERLAY_VARS_LINKAGE const HostOverlayVar gHostOvVars_##unit[] =
#define HOST_OVERLAY_VAR(v) {(void *)&(v), sizeof(v), #v}
#define HOST_OVERLAY_VARS_END {0, 0, 0}

#ifdef __cplusplus
// In an overlay unit's StaticInit_<unit> (called when the overlay is loaded, after its variables were reset): give
// an array variable its initial elements, the initialiser that the DS's __sinit ran at the load (one the compiler
// can't make constant data: member function pointers cast to another type, values read from other variables).
#define HOST_STATIC_INIT_ARRAY(var, ...)                                                                             \
    do {                                                                                                             \
        const decltype(var) init_ = __VA_ARGS__;                                                                     \
        for (__SIZE_TYPE__ i_ = 0; i_ < sizeof(var) / sizeof((var)[0]); i_++) (var)[i_] = init_[i_];                \
    } while (0)
// The same for a variable that isn't an array.
#define HOST_STATIC_INIT(var, ...)                                                                                   \
    do {                                                                                                             \
        const decltype(var) init_ = __VA_ARGS__;                                                                     \
        (var) = init_;                                                                                               \
    } while (0)

// In a StaticInit_<unit>: run the default constructor of an object (or of each element of an array) defined in the
// unit, as the DS's __sinit did at the load. (Such objects are also constructed at start-up, by the compiler's own
// static initialisation; their constructors only set their members.)
struct HostOverlayPlace {};
inline void *operator new(__SIZE_TYPE__, void *p, HostOverlayPlace) { return p; }
template <class T> inline void HostOverlay_Construct(T &v) { new (&v, HostOverlayPlace()) T; }
template <class T, __SIZE_TYPE__ N> inline void HostOverlay_Construct(T (&v)[N]) {
    for (__SIZE_TYPE__ i = 0; i < N; i++) HostOverlay_Construct(v[i]);
}
#define HOST_STATIC_CONSTRUCT(var) HostOverlay_Construct(var)
#endif

#endif
